# name: singleton_nonmember_yes
# description: Yes-rate to non-example targets after a single-example set; observed above null means people generalize more broadly from one example than the size-principle model (below null: more narrowly).
def test_statistic(df):
    s = df["number_set"].astype(str)
    single = ~s.str.contains(",")
    t = df["target"].astype(int).astype(str)
    m = (single & (s.str.strip() != t)).values
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].values[m].mean())

# name: early_minus_late_yes
# description: Yes-rate on trials with trial_index < 90 minus yes-rate on trials with trial_index >= 90; observed above null means people grow more conservative over the session, a drift the stationary model cannot produce.
def test_statistic(df):
    ti = df["trial_index"].values
    r = df["rating"].values.astype(float)
    e = ti < 90
    if e.sum() == 0 or (~e).sum() == 0:
        return 0.0
    return float(r[e].mean() - r[~e].mean())

# name: in_set_target_yes_rate
# description: Yes-rate on trials whose target is one of the shown examples; observed below null means people miss/lapse on trivially consistent targets that the lapse-free model answers "yes" to almost surely.
def test_statistic(df):
    s = df["number_set"].astype(str)
    t = df["target"].astype(int).astype(str)
    padded = "," + s.str.replace(" ", "", regex=False) + ","
    inset = np.array([("," + b + ",") in a for a, b in zip(padded.values, t.values)])
    if inset.sum() == 0:
        return 0.0
    return float(df["rating"].values[inset].mean())

# name: cell_extremity
# description: Mean over (set,target) cells of |cell yes-rate - 0.5|; observed below null means the model's predictions are over-confident (too close to 0/1) relative to graded human responding.
def test_statistic(df):
    m = df.groupby(["number_set", "target"])["rating"].mean()
    return float((m - 0.5).abs().mean())
